@startuml

class CarPark {}

class Barrier {
  + raise()
}

class CardReader {
  + verifyCardNumber()
  + sendSignal()
}

class Signal {}

class StaffCard {
  + name : string
  + department : string
  + staffNumber : string
}

class GuestCard {
  + number : string
  + currentDate : date
}

class Card {}

StaffCard extends Card
GuestCard extends Card

CarPark "1" -- "*" Barrier
CarPark "1" -- "1" CardReader
CarPark "1" -- "0..1" Signal
CardReader "1" -- "1" Signal

@enduml

